; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
vp_arr_hs:			dc.w (arr_hs)&$FFFF	; VarPtr: the address, 16 bits (RAM from $FF8000)
vp_arr_back:			dc.w (arr_back)&$FFFF	; VarPtr: the address, 16 bits (RAM from $FF8000)

